  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 What Is Entrepreneurship and Is It a Calling$j$, $j${"readings": [{"title": "Proverbs 22 (King James Version)", "url": "/portal/bible/Proverbs/22"}], "body": "An entrepreneur is a person who sees a need, organizes resources and takes a reasonable risk to meet that need through a business. Entrepreneurs create jobs, serve customers and strengthen communities. Proverbs 22:29 says, Seest thou a man diligent in his business? he shall stand before kings; he shall not stand before mean men. Diligence in work is honored in Scripture.\n\nA business is an organization that provides goods or services in exchange for money. A good is a physical product, such as a loaf of bread. A service is work done for others, such as lawn care or tutoring. The owner takes on risk, which is the chance of losing money or time, and hopes for a reward, which is profit. Profit is what remains after all costs are paid.\n\nEntrepreneurs are not only business founders. Some are self employed, some build companies, some lead nonprofits and some serve inside larger organizations with an entrepreneurial spirit. Common qualities include diligence, creativity, honesty, willingness to learn, patience, and the ability to serve people well. Not every person is called to own a business, and that is fine. Every person can learn to work with wisdom and to steward money, time and talent.\n\nFor a believer, work is a form of service to God. Colossians 3:23 teaches to work as unto the Lord, and Genesis 2:15 shows that work existed before the fall. A business can be a ministry when it is run with integrity, serves real needs and gives generously.\n\nYour task: (1) Define entrepreneur, profit and risk. (2) Name a good and a service you could offer. (3) Explain how Proverbs 22:29 applies to your work.\n\nFlorida standards: Florida Entrepreneurship course standards (course 8812100).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida Entrepreneurship course standards (course 8812100)", "script": "Welcome back. Listen, Proverbs 22:29 says, Seest thou a man diligent in his business? he shall stand before kings. Diligence in work is honored in Scripture.\n\nNow watch this. An entrepreneur sees a need, organizes resources and takes a reasonable risk to meet it. A business provides goods or services in exchange for money. A good is a product. A service is work done for others.\n\nThe owner takes risk, the chance of losing money or time, and hopes for profit, what remains after all costs are paid.\n\nEntrepreneurs include business founders, self employed people, nonprofit leaders and people who serve inside larger organizations. Key qualities are diligence, creativity, honesty and a willingness to learn.\n\nFor a believer, work is service to God. A business can be a ministry when it is run with integrity and gives generously.\n\nYour task is to define three terms, name a good and a service and explain Proverbs 22:29. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 What Is Entrepreneurship and Is It a Calling$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 Finding Needs and Business Ideas$j$, $j${"readings": [{"title": "Proverbs 14 (King James Version)", "url": "/portal/bible/Proverbs/14"}], "body": "Great businesses begin by solving a problem. Proverbs 14:23 says, In all labour there is profit: but the talk of the lips tendeth only to penury. Real work meets real needs. An idea that no one needs is only a wish.\n\nTo find ideas, begin by looking around you. What do your family, church, school or neighborhood need? What frustrates people? What takes too much time or costs too much? What skills do you have that others value? Keep an idea notebook and write down needs you see. Good sources include your own experiences, your talents and hobbies, community needs, and trends such as technology, health and education.\n\nTest your idea with simple questions. Who is the customer? What problem does the product solve? Would they pay for it? How much? Who else already offers it? Why would customers choose you? Talking to at least ten possible customers gives you real information that guessing cannot.\n\nIdeas can be a good, a service or a combination. Examples that students may consider include tutoring, lawn and garden care, car washing with permission and supervision, baked goods made in a safe kitchen with adult approval, crafts, photography, event help, and digital skills such as design or video editing. Always involve a parent or guardian when you start any real business, follow the law, never share private information such as your address with strangers, and do not meet unknown customers alone.\n\nYour task: (1) List five needs you see around you. (2) Choose one idea and answer who the customer is and what problem you solve. (3) Plan how you will ask ten people for feedback.\n\nFlorida standards: Florida Entrepreneurship course standards (course 8812100).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida Entrepreneurship course standards (course 8812100)", "script": "Welcome back. Listen, Proverbs 14:23 says, In all labour there is profit. Real work meets real needs.\n\nNow watch this. Great businesses start by solving a problem. Look around. What does your family, church, school or neighborhood need? What frustrates people? What skills do you have that others value?\n\nTest your idea. Who is the customer? What problem do you solve? Would they pay? How much? Who else offers it? Why would they choose you? Ask at least ten possible customers. Real information beats guessing.\n\nIdeas can be goods, services or both. Examples are tutoring, yard care, baked goods made safely with adult approval, crafts, photography and digital skills.\n\nFor any real business, involve a parent or guardian, follow the law, protect private information and never meet unknown customers alone.\n\nYour task is to list five needs, choose one idea and plan ten conversations. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 Finding Needs and Business Ideas$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 Character, Ethics and Integrity in Business$j$, $j${"readings": [{"title": "Proverbs 11 (King James Version)", "url": "/portal/bible/Proverbs/11"}], "body": "A business is built on trust, and trust is built on character. Proverbs 11:1 says, A false balance is abomination to the LORD: but a just weight is his delight. Proverbs 20:23 says, Divers weights are an abomination unto the LORD; and a false balance is not good. Honest dealing pleases God and protects your name.\n\nEthics are the moral principles that guide choices. Ethical business owners tell the truth in advertising, price fairly, keep promises, pay what they owe, treat workers and customers with respect, and refuse to cheat even when no one is watching. Unethical behavior includes lying about a product, hiding fees, copying another person's work, stealing ideas or images, and treating people unfairly. Dishonesty may bring quick money, but it destroys trust and often leads to lawsuits or loss of the business.\n\nIntegrity means being the same person in public and in private. Jesus taught in Matthew 7:12, Therefore all things whatsoever ye would that men should do to you, do ye even so to them. That rule helps in every decision. Ask: Would I be comfortable if the customer saw exactly how I made this decision? Would I want to be treated this way?\n\nWhen you make a mistake, admit it quickly, fix it and learn from it. Proverbs 28:13 says, He that covereth his sins shall not prosper: but whoso confesseth and forsaketh them shall have mercy. Reputation is your most valuable asset.\n\nYour task: (1) Define ethics and integrity. (2) Describe three honest business habits. (3) Explain how Matthew 7:12 helps you decide a hard case.\n\nFlorida standards: Florida Entrepreneurship course standards (course 8812100).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida Entrepreneurship course standards (course 8812100)", "script": "Welcome back. Listen, Proverbs 11:1 says, A false balance is abomination to the LORD: but a just weight is his delight. Honest dealing pleases God and protects your name.\n\nNow watch this. A business is built on trust, and trust is built on character. Ethics are the moral principles that guide choices. Ethical owners tell the truth in advertising, price fairly, keep promises, pay what they owe and treat people with respect.\n\nUnethical behavior includes lying about a product, hiding fees, copying another person's work and treating people unfairly.\n\nIntegrity means being the same in public and in private. Matthew 7:12 gives the rule: do to others what you would want done to you.\n\nIf you make a mistake, admit it quickly, fix it and learn. Your reputation is your most valuable asset.\n\nYour task is to define two terms, list three honest habits and apply Matthew 7:12. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 Character, Ethics and Integrity in Business$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 Business Structures and Legal Basics$j$, $j${"readings": [{"title": "Romans 13 (King James Version)", "url": "/portal/bible/Romans/13"}], "body": "Every business has a legal form. Choosing the right form affects taxes, risk and paperwork. This lesson is general education and not legal or tax advice. A real business owner should consult a licensed attorney, accountant or the appropriate government office. Romans 13:1 teaches respect for lawful authority, and following the law protects your business.\n\nA sole proprietorship is owned by one person. It is simple and cheap to start, but the owner is personally responsible for the debts and legal claims of the business. A partnership has two or more owners who share profits and responsibility. A limited liability company, called an LLC, is a separate legal entity that can protect the owner's personal property from many business debts. A corporation is a separate legal entity owned by shareholders and is more complex. A nonprofit organization uses its income to serve a mission rather than to pay owners, and may qualify for tax exempt status after meeting legal requirements.\n\nIn Florida, businesses commonly register through the Florida Division of Corporations at Sunbiz.org, may need local business tax receipts from the city or county, and may need licenses depending on the type of work. Many businesses also need an Employer Identification Number, called an EIN, from the Internal Revenue Service. Food, childcare, home repair and many other fields have additional rules. Contracts, insurance and written agreements protect both sides.\n\nMinors have special limits. In most places a person under eighteen cannot sign a binding contract alone, so a parent or guardian must help set up any real business. Intellectual property such as trademarks, copyrights and patents protects names, creative works and inventions.\n\nYour task: (1) Compare a sole proprietorship and an LLC. (2) Name three legal steps a Florida business may need. (3) Explain why a student needs a parent or guardian to start a real business.\n\nFlorida standards: Florida Entrepreneurship course standards (course 8812100).", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "Florida Entrepreneurship course standards (course 8812100)", "script": "Welcome back. Listen, Romans 13:1 teaches respect for lawful authority, and following the law protects your business. This lesson is general education, not legal or tax advice.\n\nNow watch this. A sole proprietorship has one owner, is simple, but the owner is personally responsible for debts. A partnership has two or more owners. An LLC is a separate legal entity that can protect personal property. A corporation is owned by shareholders. A nonprofit uses income for a mission and may qualify for tax exempt status.\n\nIn Florida, businesses commonly register at Sunbiz.org, may need a local business tax receipt, licenses for certain work, and an EIN from the IRS.\n\nMinors usually cannot sign binding contracts alone, so a parent or guardian must help with any real business. Trademarks, copyrights and patents protect names, creative works and inventions.\n\nYour task is to compare two structures, name three legal steps and explain why adult help is needed. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 Business Structures and Legal Basics$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Foundations of Entrepreneurship$j$, $j${"prompt": "Write a report of at least 250 words. Use complete sentences and label each part. Proverbs 22:29 says, Seest thou a man diligent in his business? he shall stand before kings; he shall not stand before mean men.\n\nPart 1: Define entrepreneur, business, good, service, risk and profit. Explain whether every person must own a business to be a good steward.\nPart 2: Describe three ways to find a business idea and how to test an idea with ten possible customers.\nPart 3: Explain ethics and integrity, give three examples of honest and three examples of dishonest business behavior, and explain Proverbs 11:1.\nPart 4: Compare a sole proprietorship, an LLC and a nonprofit, name three legal steps a Florida business may need and explain why a student needs a parent or guardian. Note that this is general education and not legal advice.\nPart 5: Explain how Proverbs 22:29 and Colossians 3:23 shape how you will work.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 25 points. Part 4: 25 points. Part 5: 5 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Foundations of Entrepreneurship$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Diligent in His Business$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a need you see in your church, school or neighborhood, (2) explains a business or service idea that could meet it, (3) explains why honesty is the most important quality for the owner, and (4) connects your answer to Proverbs 22:29, Proverbs 14:23 or Proverbs 11:1. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Can a business be a ministry? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Diligent in His Business$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: What Is Entrepreneurship and Is It a Calling$j$, $j${"questions": [{"q": "An entrepreneur is a person who:", "options": ["Sees a need and builds a way to meet it", "Never earns money", "Avoids all risk", "Only works for others"]}, {"q": "Profit is:", "options": ["Only your salary", "All the money you receive", "The price of a product", "What remains after all costs are paid"]}, {"q": "Lawn care is an example of a:", "options": ["Loan", "Service", "Tax", "Good"]}, {"q": "Risk is:", "options": ["A price", "A guaranteed profit", "The chance of losing money or time", "A kind of tax"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: What Is Entrepreneurship and Is It a Calling$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,1,2}'::int[], array[$j$Entrepreneurs organize resources to meet needs.$j$,$j$Profit equals revenue minus costs.$j$,$j$A service is work done for others.$j$,$j$Every business carries risk.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: What Is Entrepreneurship and Is It a Calling$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: Finding Needs and Business Ideas$j$, $j${"questions": [{"q": "Great businesses usually begin by:", "options": ["Guessing prices", "Copying a logo", "Avoiding customers", "Solving a real problem"]}, {"q": "The best way to test an idea is to:", "options": ["Wait for luck", "Ask no one", "Borrow money first", "Ask possible customers"]}, {"q": "When a student starts a real business, they should:", "options": ["Share their home address online", "Involve a parent or guardian", "Hide it from adults", "Meet strangers alone"]}, {"q": "A good is:", "options": ["A physical product", "Work done for others", "A kind of risk", "A tax"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Finding Needs and Business Ideas$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,3,1,0}'::int[], array[$j$A real need creates a real market.$j$,$j$Customer feedback gives real information.$j$,$j$Adult involvement keeps young people safe.$j$,$j$A good is a product you can touch.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Finding Needs and Business Ideas$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Character, Ethics and Integrity in Business$j$, $j${"questions": [{"q": "Ethics are:", "options": ["Moral principles that guide choices", "Business loans", "Ways to advertise", "Types of taxes"]}, {"q": "Which is an honest business habit?", "options": ["Hiding fees", "Breaking promises", "Telling the truth in advertising", "Copying another person's work"]}, {"q": "Integrity means:", "options": ["Avoiding customers", "Working alone", "Making the most money", "Being the same in public and in private"]}, {"q": "Your most valuable business asset is often your:", "options": ["Logo", "Slogan", "Office", "Reputation"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Character, Ethics and Integrity in Business$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,3,3}'::int[], array[$j$Ethics guide right and wrong decisions.$j$,$j$Honest advertising builds trust.$j$,$j$Integrity is consistent character.$j$,$j$Trust and a good name last longer than money.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Character, Ethics and Integrity in Business$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: Business Structures and Legal Basics$j$, $j${"questions": [{"q": "A sole proprietorship is owned by:", "options": ["Two or more partners", "The government", "One person", "Shareholders only"]}, {"q": "An LLC can help protect:", "options": ["The owner's personal property from many business debts", "The business from all taxes", "Products from rust", "Customers from prices"]}, {"q": "Florida businesses commonly register through:", "options": ["A newspaper", "A school", "A bank only", "Sunbiz.org"]}, {"q": "Why does a student need a parent or guardian to start a real business?", "options": ["Adults pay no taxes", "It is optional and useless", "Businesses are illegal for students", "Minors usually cannot sign binding contracts alone"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Business Structures and Legal Basics$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,3,3}'::int[], array[$j$Sole means one owner.$j$,$j$LLC stands for limited liability company.$j$,$j$Sunbiz is the Division of Corporations site.$j$,$j$Contracts generally require an adult.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: Business Structures and Legal Basics$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: Foundations of Entrepreneurship$j$, $j${"questions": [{"q": "Which is a service?", "options": ["A lawn mower", "Tutoring", "A loaf of bread", "A notebook"]}, {"q": "Profit equals:", "options": ["Revenue plus costs", "Costs minus revenue", "Revenue minus costs", "Price times two"]}, {"q": "An idea nobody needs is likely to:", "options": ["Succeed automatically", "Be free", "Fail", "Be a corporation"]}, {"q": "A good way to test an idea is to:", "options": ["Copy a rival exactly", "Ask no one", "Spend all your savings", "Ask possible customers"]}, {"q": "A false balance is described in Proverbs 11:1 as:", "options": ["An abomination to the LORD", "A kind of loan", "A good name", "A smart tool"]}, {"q": "Integrity means:", "options": ["The same character in public and private", "Hiding mistakes", "Pleasing everyone", "Avoiding rules"]}, {"q": "A business structure that can protect personal property from many business debts is the:", "options": ["Sole proprietorship", "LLC", "Gift", "Hobby"]}, {"q": "The Employer Identification Number comes from the:", "options": ["Local school", "Post office", "Internal Revenue Service", "Church board"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Foundations of Entrepreneurship$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,2,2,3,0,0,1,2}'::int[], array[$j$A service is work done for others.$j$,$j$What remains after costs.$j$,$j$Business must meet real needs.$j$,$j$Real feedback reduces risk.$j$,$j$God hates dishonest scales.$j$,$j$Integrity is consistent honesty.$j$,$j$LLC is a limited liability company.$j$,$j$The IRS issues EINs.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Foundations of Entrepreneurship$j$ on conflict (item_id) do nothing;
